import sys
import os
import math

def format_size(s):
    if s < 1024:
        return f"{s}B"
    for unit in ['K', 'M', 'G', 'T']:
        s /= 1024.0
        val = round(s, 1)
        if val < 10.0:
            return f"{s:.1f}{unit}"
        elif val < 1024.0:
            return f"{round(s)}{unit}"
    return f"{round(s)}P"

def get_size(path, apparent):
    try:
        st = os.lstat(path)
    except Exception:
        return 0
    if apparent:
        size = st.st_size
    else:
        size = st.st_blocks * 512 if hasattr(st, 'st_blocks') else st.st_size
    return size

class Node:
    def __init__(self, path, apparent):
        self.path = path
        self.name = os.path.basename(path) or path
        self.apparent = apparent
        self.size = 0
        self.children = []
        self.is_dir = os.path.isdir(path) and not os.path.islink(path)
        self.st_size = get_size(path, apparent)

    def populate(self):
        if self.is_dir:
            self.size = self.st_size
            try:
                for entry in os.scandir(self.path):
                    child = Node(entry.path, self.apparent)
                    child.populate()
                    self.children.append(child)
                    self.size += child.size
            except Exception:
                pass
        else:
            self.size = self.st_size

